  // respawned nearer, so the streets always feel alive.
  const px = G.player.x;
  const py = G.player.y;
  for (const car of G.cars) {
    if (car.driver !== 'traffic') continue;
    if (Math.hypot(car.x - px, car.y - py) > 1600) {
      const p = G.city.randomRoadPoint();
      car.x = p.x;
      car.y = p.y;
      car.angle = p.angle;
      car.target = null;
    }
  }
}
