    const s = G.city.spots.taxiStand;
    G.player.x = s.x;
    G.player.y = s.y;
    G.camera.x = Math.max(0, Math.min(2800 - 1280, s.x - 640));
    G.camera.y = Math.max(0, Math.min(2800 - 720, s.y - 360));
    let walkTarget = G.city.randomSidewalkPoint();
