    // paint shop, the waypoint marker and objective on the HUD.
    G.missions.taxiCooldown = 30;
    putInCar(G, 'sedan', 1000, 480, Math.PI / 2);
    G.player.car.speed = 200;
    const shop = G.city.spots.paintShop;
