  G.cars = G.cars.filter((c) => !(c.driver !== 'player' && c.x > 1200 && c.x < 1600 && c.y > 400 && c.y < 2600));
  G.peds = G.peds.filter((p) => !(p.x > 1280 && p.x < 1520 && p.y > 400 && p.y < 2600));
